/**
 * Tests for no-unsafe-query
 * CWE-943 — Prevent NoSQL injection via direct use of user input in MongoDB queries
 *
 * Generated by: node scripts/generate-rule-tests.mjs
 * Standard: Engineering Standards §5 (side-by-side), §6 (≥5 valid + ≥5 invalid), §8 (RuleTester at describe level)
 */
import { RuleTester } from '@typescript-eslint/rule-tester';
import { describe, it, afterAll } from 'vitest';
import parser from '@typescript-eslint/parser';
import { noUnsafeQuery } from './index';

/**
 * Every fixture imports mongoose, because the rules now abstain in files with
 * no Mongo in them. Wrapping the arrays rather than editing each fixture means
 * one cannot be left behind — a fixture missing the import would pass
 * vacuously on the gate instead of exercising the detection it was written
 * for. `output` and errors[].suggestions[].output are prefixed too, since
 * autofix fixtures assert the whole file back.
 */
// A SIDE-EFFECT import: satisfies the gate without reserving any binding, so
// fixtures that already declare `mongoose`/`db` do not redeclare.
const asMongo = (code: string): string => `import 'mongoose';\n${code}`;
type MongoSuggestion = { output?: string | null };
type MongoCase = {
  code: string;
  output?: string | null;
  errors?: ReadonlyArray<{ suggestions?: readonly MongoSuggestion[] } | string>;
};
const xmo = <T,>(cases: T[]): T[] =>
  cases.map((c) => {
    if (typeof c === 'string') return asMongo(c) as T;
    const test = c as MongoCase;
    return {
      ...c,
      code: asMongo(test.code),
      ...(typeof test.output === 'string' ? { output: asMongo(test.output) } : {}),
      ...(test.errors
        ? {
            errors: test.errors.map((e) =>
              typeof e === 'string' || !Array.isArray(e.suggestions)
                ? e
                : {
                    ...e,
                    suggestions: e.suggestions.map((s) =>
                      typeof s.output === 'string'
                        ? { ...s, output: asMongo(s.output) }
                        : s,
                    ),
                  },
            ),
          }
        : {}),
    } as T;
  });


RuleTester.afterAll = afterAll;
RuleTester.it = it;
RuleTester.itOnly = it.only;
RuleTester.describe = describe;

const ruleTester = new RuleTester({
  languageOptions: {
    parser,
    ecmaVersion: 2022,
    sourceType: 'module',
    parserOptions: { ecmaFeatures: { jsx: true } },
  },
});

describe('no-unsafe-query', () => {
  describe('Valid Code', () => {
    ruleTester.run('valid - safe patterns', noUnsafeQuery, {
      valid: xmo([
        // Unrelated code should not trigger
        {
          code: `const x = 1;`,
        },
        // Array operations are safe
        {
          code: `const arr = [1, 2, 3];`,
        },
        // Non-targeted method calls are safe
        {
          code: `obj.safeMethod();`,
        },
        // Static property values are safe
        {
          code: `const config = { key: "static-value" };`,
        },
        // Allowed in test files
        {
          code: `if (x == y) {}`,
          filename: 'test.spec.ts',
          options: [{"allowInTests":true}],
        },
      ]),
      invalid: [],
    });
  });

  describe('Invalid Code', () => {
    ruleTester.run('invalid - dangerous patterns', noUnsafeQuery, {
      valid: [],
      invalid: xmo([
        // Triggers unsafeQuery: user input in query
        {
          code: `db.users.find({ username: req.body.username });`,
          errors: [{
            messageId: 'unsafeQuery',
            suggestions: [{ messageId: 'suggestionUseEq', output: `db.users.find({ username: { $eq: req.body.username } });` }],
          }],
        },
      ]),
    });
  });

  /**
   * Labelled-corpus regression. These fixtures are **deliberately not** run
   * through `xmo()`: they carry no `mongodb` import, which is the entire point.
   * The native-driver arm in `mongo-evidence.ts` is what opens the gate for
   * them, and prefixing an import would make them pass on the unfixed code.
   */
  describe('CWE-943 corpus — native driver, no import', () => {
    ruleTester.run('native-driver collection handles', noUnsafeQuery, {
      valid: [
        {
          // benchmarks/corpus/CWE-943/safe/explicit-eq.js
          name: 'user input wrapped in $eq is not reported',
          code: [
            `async function login(req, res) {`,
            `  const user = await db.collection('users').findOne({`,
            `    username: { $eq: String(req.body.username) },`,
            `    password: { $eq: String(req.body.password) },`,
            `  }, { projection: { _id: 1, username: 1, role: 1 } });`,
            `  return user;`,
            `}`,
          ].join('\n'),
        },
        {
          // benchmarks/corpus/CWE-943/safe/static-filter.js
          name: 'a fully static filter is not reported',
          code: [
            `async function fetchActiveAdmins() {`,
            `  return db.collection('users').find({`,
            `    role: 'superuser',`,
            `    status: 'active',`,
            `  }, { limit: 100, projection: { _id: 1, username: 1, role: 1 } }).toArray();`,
            `}`,
          ].join('\n'),
        },
        {
          // Firestore spells the handle the same way and must stay closed: the
          // gate never opens, so the rule registers no visitors at all.
          name: 'a Firestore collection reference does not open the gate',
          code: `const snap = await db.collection('users').doc(id).get();\ndb.collection('users').where('name', '==', req.query.name).get();`,
        },
      ],
      invalid: [
        {
          // benchmarks/corpus/CWE-943/vulnerable/user-input-in-find.js
          name: 'user input reaches a native-driver findOne',
          code: [
            `async function login(req, res) {`,
            `  const user = await db.collection('users').findOne({`,
            `    username: req.body.username,`,
            `    password: req.body.password,`,
            `  });`,
            `  return user;`,
            `}`,
          ].join('\n'),
          errors: [
            {
              messageId: 'unsafeQuery' as const,
              suggestions: [
                {
                  messageId: 'suggestionUseEq' as const,
                  output: [
                    `async function login(req, res) {`,
                    `  const user = await db.collection('users').findOne({`,
                    `    username: { $eq: req.body.username },`,
                    `    password: req.body.password,`,
                    `  });`,
                    `  return user;`,
                    `}`,
                  ].join('\n'),
                },
              ],
            },
            {
              messageId: 'unsafeQuery' as const,
              suggestions: [
                {
                  messageId: 'suggestionUseEq' as const,
                  output: [
                    `async function login(req, res) {`,
                    `  const user = await db.collection('users').findOne({`,
                    `    username: req.body.username,`,
                    `    password: { $eq: req.body.password },`,
                    `  });`,
                    `  return user;`,
                    `}`,
                  ].join('\n'),
                },
              ],
            },
          ],
        },
        {
          // benchmarks/corpus/CWE-943/vulnerable/where-string.js — reached
          // through `.toArray()`, not `.find()`: `find` is deliberately not in
          // the native-driver method set.
          name: 'a template-literal $where reaches a native-driver cursor',
          code: [
            `async function searchByName(req) {`,
            `  return db.collection('items').find({`,
            "    $where: `this.name == '${req.query.name}'`,",
            `  }).toArray();`,
            `}`,
          ].join('\n'),
          errors: [
            {
              messageId: 'unsafeQuery' as const,
              suggestions: [
                {
                  messageId: 'suggestionUseEq' as const,
                  output: [
                    `async function searchByName(req) {`,
                    `  return db.collection('items').find({`,
                    "    $where: { $eq: `this.name == '${req.query.name}'` },",
                    `  }).toArray();`,
                    `}`,
                  ].join('\n'),
                },
              ],
            },
          ],
        },
      ],
    });
  });
});
